# owner: platform
import unittest

from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("s1", "Lovelace", "Ada", "A")

# ---
def mark(when, status="absent", owner="s1"):
    return Mark(owner, date(2026, 3, when), status)

class NoticeTests(unittest.TestCase):
    def test_names_student_count_and_dates(self):
        marks = [mark(9), mark(4), mark(5, "present")]
        text = absence_notice(PUPIL, marks)
        self.assertIn("Ada Lovelace missed 2 days", text)
        self.assertLess(
            text.index("March 4, 2026"),
            text.index("March 9, 2026"),
        )

    def test_single_day_is_singular(self):
        text = absence_notice(PUPIL, [mark(4)])
        self.assertIn("missed 1 day of", text)

    def test_excused_days_are_left_out(self):
        marks = [mark(4), mark(5, "excused")]
        text = absence_notice(PUPIL, marks)
        self.assertNotIn("March 5", text)

    def test_accepts_any_iterable(self):
        text = absence_notice(PUPIL, iter([mark(4)]))
        self.assertIn("March 4, 2026", text)

class NoticeErrorTests(unittest.TestCase):
    def test_foreign_mark_is_rejected(self):
        marks = [mark(4), mark(5, owner="s2")]
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, marks)

    def test_no_absences_is_rejected(self):
        marks = [mark(4, "present"), mark(5, "late")]
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, marks)

    def test_empty_marks_are_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, [])
